INSERT INTO "public"."mlmdata" ("id", "title1", "lyrics", "lyricseng", "title2", "choavbl", "key", "min_maj", "auth", "bpm", "rhythm", "timesignature", "tags", "ytlink", "vvsongno", "chords", "pref.chord") VALUES (274767, 'Aa aa aa aa ennu kanum yeshu', 'ആ.. ആ.. ആ.. ആ..<BR>എന്നു കാണും യേശുരാജനെ<BR>കാലമായ് കാലമായ് പറന്നുപോകാൻ കാലമായ് <BR>രാജാധിരാജൻ വരുന്നു വേഗം പ്രിയരെ<slide>1 കാഹളനാദം കേട്ടിടുന്ന നാളിൽ<BR>ഹല്ലേലുയ്യാ ഗീതം പാടിടുമേ അന്നു ഞാൻ;-<slide>2 എന്നിനി ഞാൻ ചേർന്നിടും പൊന്നുമുഖം കാണുവാൻ<BR>ശോഭയേറും നാട്ടിൽ ഞാൻ പോയിടുവാൻ കാലമായ്;-<slide>3 ലോകത്തിൽ ഞാനൊരു നിന്ദിതനെങ്കിലും<BR>മേഘത്തിൽ ഞാനൊരു വധുവായ് വാഴുമെ;-<slide>4 യേശുരാജൻ വന്നിടും ഭക്തന്മാരെ ചേർക്കുവാൻ<BR>സ്വർഗ്ഗാധിസ്വർഗ്ഗങ്ങളിൽ വാസം ചെയ് വാൻ കാലമായ്;-<slide>5 മുൾക്കിരീടധാരിയായ് കടന്നുപോയ പ്രിയനെ<BR>പൊൻകിരീടധാരിയായ് അന്നു ഞാൻ കാണുമെ;-<slide>', 'aa… aa… aa… aa… <BR>ennu kanum yeshu raajane<BR>kaalamay kaalamay parannu pokaan kaalamay<BR>raajaadhiraajan varunnu vegam priyare<slide>1 kaahala naadam kettidunna naalil<BR>halleluyah! getham paadidume annu njaan;-<slide>2 ennini njaan chernnidum ponnumokham kaanuvan<BR>shobhayerum naattil njaan poyiduvaan kaalamaay;-<slide>3 lokathil njaanoru nindithan-engkilum<BR>meghathil njaanoru vadhuvay vaazhume;-<slide>4 yeshuraajan vannidum bhakthanmare cherkkuvan<BR>swarggaadhi swarggangalil vaasam cheyvan kaalamay;-<slide>5 mulkkiredadhariyay kadannupoya priyane<BR>ponkireda-dhariyay annu njaan kaanume;-<slide>', 'ആ ആ ആ ആ എന്നു കാണും യേശു', 1, 'Am', null, null, '100', 'R&B - 6-8SlowRock / Jazz - Orchestral6-8', '6/8', null, 'https://www.youtube.com/watch?v=k3yqCtGaS0g', '1', '[Am]Aa-Aa-Aa-Aa- [G]ennu kanum [F]yeshu raj[Am]ane<BR>[Am]kaalamai [F]kaalamai [G]parannu povan [Am]kalamai<BR>[C]rajathi[Dm]rajan [F]varunnu vegam [Am]priyare!<slide>
